+import { Pool } from "pg";
+import * as fs from "fs";
+import * as path from "path";
+
+const pool = new Pool({ connectionString: process.env.DATABASE_URL });
+
+interface ColumnInfo {
+  name: string;
+  type: string;
+  is_nullable: boolean;
+}
+
+async function introspectSchema() {
+  try {
+    const result = await pool.query(`
+      SELECT
+        t.table_name,
+        c.column_name,
+        c.data_type,
+        c.is_nullable
+      FROM information_schema.tables t
+      JOIN information_schema.columns c
+        ON t.table_schema = c.table_schema
+        AND t.table_name = c.table_name
+      WHERE t.table_schema = 'public'
+      ORDER BY t.table_name, c.ordinal_position
+    `);
+
+    const schema: Record<string, Record<string, string>> = {};
+
+    for (const row of result.rows) {
+      if (!schema[row.table_name]) {
+        schema[row.table_name] = {};
+      }
+      schema[row.table_name][row.column_name] = row.data_type;
+    }
+
+    const schemaCode = `export const schema = ${JSON.stringify(schema, null, 2)} as const;
+
+export type TableName = keyof typeof schema;
+export type ColumnName<T extends TableName> = keyof typeof schema[T];
+`;
+
+    const outputPath = path.join(process.cwd(), "src/db/schema.ts");
+    fs.writeFileSync(outputPath, schemaCode);
+    console.log(`✓ Generated schema at ${outputPath}`);
+    console.log(`  Tables: ${Object.keys(schema).join(", ")}`);
+  } catch (error) {
+    console.error("Failed to introspect schema:", error);
+    process.exit(1);
+  } finally {
+    await pool.end();
+  }
+}
+
+introspectSchema();
