@@ -0,0 +1,65 @@
+import * as fs from "fs";
+import * as path from "path";
+import { validateQuery } from "../src/db/validate.ts";
+
+function extractQueries(code: string): { query: string; line: number }[] {
+  const queries: { query: string; line: number }[] = [];
+  const lines = code.split("\n");
+  const queryRegex = /pool\.query\s*\(\s*["']([^"']+)["']/g;
+
+  for (let i = 0; i < lines.length; i++) {
+    let match;
+    const line = lines[i];
+    while ((match = queryRegex.exec(line)) !== null) {
+      queries.push({ query: match[1], line: i + 1 });
+    }
+  }
+
+  return queries;
+}
+
+function validateQueriesInFile(filePath: string): { valid: boolean; errors: string[] } {
+  const content = fs.readFileSync(filePath, "utf-8");
+  const queries = extractQueries(content);
+  const errors: string[] = [];
+
+  for (const { query, line } of queries) {
+    const result = validateQuery(query);
+    if (!result.valid) {
+      errors.push(`${path.relative(".", filePath)}:${line} - ${result.errors.join(", ")}`);
+    }
+  }
+
+  return { valid: errors.length === 0, errors };
+}
+
+function walkDir(dir: string, callback: (file: string) => void) {
+  const files = fs.readdirSync(dir);
+  for (const file of files) {
+    const filePath = path.join(dir, file);
+    const stat = fs.statSync(filePath);
+    if (stat.isDirectory()) {
+      if (!filePath.includes("node_modules") && !filePath.includes(".git")) {
+        walkDir(filePath, callback);
+      }
+    } else if (file.endsWith(".ts")) {
+      callback(filePath);
+    }
+  }
+}
+
+console.log("Validating SQL queries...\n");
+
+const allErrors: string[] = [];
+walkDir("src", (file) => {
+  const result = validateQueriesInFile(file);
+  allErrors.push(...result.errors);
+});
+
+if (allErrors.length > 0) {
+  console.error("❌ Query validation failed:\n");
+  allErrors.forEach(err => console.error(`  ${err}`));
+  process.exit(1);
+} else {
+  console.log("✓ All queries are valid");
+}
