@@ -0,0 +1,85 @@
+import { schema, type TableName, type ColumnName } from "./schema.ts";
+
+interface ValidationResult {
+  valid: boolean;
+  errors: string[];
+}
+
+const extractColumnsFromSelect = (sql: string): { table: string; columns: string[] }[] => {
+  const results: { table: string; columns: string[] }[] = [];
+  const selectRegex = /SELECT\s+([\w\s,*]+)\s+FROM\s+(\w+)/gi;
+  let match;
+
+  while ((match = selectRegex.exec(sql)) !== null) {
+    const columnsStr = match[1].trim();
+    const table = match[2].toLowerCase();
+    const columns = columnsStr === "*"
+      ? Object.keys(schema[table as TableName] || {})
+      : columnsStr.split(",").map(col => col.trim().split(" ").pop()).filter(Boolean) as string[];
+
+    results.push({ table, columns });
+  }
+
+  return results;
+};
+
+const extractColumnsFromInsert = (sql: string): { table: string; columns: string[] }[] => {
+  const results: { table: string; columns: string[] }[] = [];
+  const insertRegex = /INSERT\s+INTO\s+(\w+)\s*\(([\w\s,]+)\)/gi;
+  let match;
+
+  while ((match = insertRegex.exec(sql)) !== null) {
+    const table = match[1].toLowerCase();
+    const columns = match[2].split(",").map(col => col.trim()).filter(Boolean);
+    results.push({ table, columns });
+  }
+
+  return results;
+};
+
+export const validateQuery = (sql: string): ValidationResult => {
+  const errors: string[] = [];
+
+  const selectOps = extractColumnsFromSelect(sql);
+  const insertOps = extractColumnsFromInsert(sql);
+
+  for (const { table, columns } of selectOps) {
+    const tableSchema = schema[table as TableName];
+    if (!tableSchema) {
+      errors.push(`Table "${table}" does not exist in schema`);
+      continue;
+    }
+
+    for (const col of columns) {
+      if (!(col in tableSchema)) {
+        errors.push(`Column "${col}" does not exist in table "${table}"`);
+      }
+    }
+  }
+
+  for (const { table, columns } of insertOps) {
+    const tableSchema = schema[table as TableName];
+    if (!tableSchema) {
+      errors.push(`Table "${table}" does not exist in schema`);
+      continue;
+    }
+
+    for (const col of columns) {
+      if (!(col in tableSchema)) {
+        errors.push(`Column "${col}" does not exist in table "${table}"`);
+      }
+    }
+  }
+
+  return {
+    valid: errors.length === 0,
+    errors,
+  };
+};
+
+export const assertQueryValid = (sql: string): void => {
+  const result = validateQuery(sql);
+  if (!result.valid) {
+    throw new Error(`Invalid SQL query:\n${result.errors.join("\n")}`);
+  }
+};
